/bin/bash -lc 'curl --silent --show-error --max-time 10 --dump-header reed-response.headers --output reed-response.html -- "$(cat route.txt)" && head -n 1 reed-response.headers && wc -c reed-response.html && python - <<'"'PY'
from html.parser import HTMLParser
class Page(HTMLParser):
    def __init__(self): super().__init__(); self.tags=[]
    def handle_starttag(self, tag, attrs):
        fields=dict(attrs)
        if tag in {'title','h1','button'} or fields.get('role')=='status': self.tags.append(tag); print(tag, attrs)
    def handle_endtag(self, tag):
        if self.tags and self.tags[-1]==tag: self.tags.pop()
    def handle_data(self, data):
        if self.tags: print(repr(data))
Page().feed(open('reed-response.html').read())
PY"

